def test_scan_cargo_no_lockfile(tmp_path: Path) -> None:
    """Test scan_cargo when Cargo.lock doesn't exist."""
    section = scan_cargo(str(tmp_path), timeout_s=10.0)

    assert section.title == "Rust (Cargo)"
    assert len(section.rows) == 0


def test_scan_cargo_with_dependencies(tmp_path: Path) -> None:
    """Test full scan with Cargo.lock integration and version comparison."""
    cargo_lock = """
[[package]]
name = "serde"
version = "1.0.190"
source = "registry+https://github.com/rust-lang/crates.io-index"

[[package]]
name = "tokio"
version = "1.35.0"
source = "registry+https://github.com/rust-lang/crates.io-index"
    """.strip()

    cargo_lock_path = tmp_path / "Cargo.lock"
    cargo_lock_path.write_text(cargo_lock)

    # Mock crates.io responses
    def mock_get_json(url: str, timeout_s: float):
        if "serde" in url:
            return (
                HttpResult(
                    ok=True, status=200, text=json.dumps({"crate": {"max_version": "1.0.195"}})
                ),
                {"crate": {"max_version": "1.0.195"}},
            )
        elif "tokio" in url:
            return (
                HttpResult(
                    ok=True, status=200, text=json.dumps({"crate": {"max_version": "1.35.0"}})
                ),
                {"crate": {"max_version": "1.35.0"}},
            )
        return (HttpResult(ok=False, status=404, text="not found", error="not found"), None)

    with patch("version_info.registry_cargo.get_json", side_effect=mock_get_json):
        section = scan_cargo(str(tmp_path), timeout_s=10.0)

    assert section.title == "Rust (Cargo)"
    assert len(section.rows) == 2

    # serde should show update available
    serde_row = section.rows[0]
    assert serde_row.name == "serde"
    assert serde_row.current.value == "1.0.190"
    assert serde_row.latest.value == "1.0.195"
    assert serde_row.state == State.update_available
    assert serde_row.source == "Cargo.lock"

    # tokio should be up-to-date
    tokio_row = section.rows[1]
    assert tokio_row.name == "tokio"
    assert tokio_row.current.value == "1.35.0"
    assert tokio_row.latest.value == "1.35.0"
    assert tokio_row.state == State.ok
    assert tokio_row.source == "Cargo.lock"


def test_scan_cargo_handles_registry_errors(tmp_path: Path) -> None:
    """Test that registry errors are properly propagated to row state."""
    cargo_lock = """
[[package]]
name = "unknown-crate"
version = "0.1.0"
source = "registry+https://github.com/rust-lang/crates.io-index"
    """.strip()

    cargo_lock_path = tmp_path / "Cargo.lock"
    cargo_lock_path.write_text(cargo_lock)

    mock_response = HttpResult(ok=False, status=404, text="not found", error="not found")

    with patch("version_info.registry_cargo.get_json", return_value=(mock_response, None)):
        section = scan_cargo(str(tmp_path), timeout_s=10.0)

    assert len(section.rows) == 1
    row = section.rows[0]
    assert row.name == "unknown-crate"
    assert row.state == State.not_found
    assert row.latest.value is None
